referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const cache = new Map();
  const values = [];
  let executions = 0;
  for (const args of d.calls) {
    const key = JSON.stringify(args);
    if (!cache.has(key)) {
      executions++;
      cache.set(
        key,
        args.reduce((a, b) => a + b, 0),
      );
    }
    values.push(cache.get(key));
  }
  return { values, executions };
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const cache = new Map<string, number>();
  const values: number[] = [];
  let executions = 0;
  for (const args of d.calls) {
    const key = JSON.stringify(args);
    if (!cache.has(key)) {
      executions++;
      cache.set(
        key,
        args.reduce((a: number, b: number) => a + b, 0),
      );
    }
    values.push(cache.get(key)!);
  }
  return { values, executions };
}
